model:
rachana: 1
sutra: scenario-set
version: 1
description: 
match: { kind: scenario-set, priority: 10 }
title: { pill: "Market risk · Scenario set", id: "$.SCENARIO_SET_ID", with: "$.DESCRIPTION" }
strip:
  - { label: "Business date", bind: "$.BUSINESS_DATE" }
  - { label: "Scenarios", bind: "$.SCENARIO_COUNT", fmt: "amount0", emphasis: true }
  - { label: "Window start", bind: "$.WINDOW_START" }
  - { label: "Window end", bind: "$.WINDOW_END" }
  - { label: "Horizon (days)", bind: "$.HORIZON_DAYS" }
  - { label: "Revaluation", bind: "$.REVALUATION" }
  - { label: "Batch", bind: "$.SOURCE_BATCH" }
panels:
  - id: days
    kind: table
    title: "Scenario days (index i is the position in every vector of the date)"
    key: "F2"
    code: "DAYS"
    rows: "$.SCENARIO_DATES"
    limit: 30
    empty: "No scenario days"
    columns:
      - { label: "Index i", bind: "#index" }
      - { label: "Scenario day", bind: "@" }
  - id: note
    kind: markdown
    title: "Every vector of the date is in this order"
    area: right
    phone: { tier: "more", from: "fragment" }
    text: "Position i of every P&L vector, scenario PV vector and FX scenario (RATES) of ${$.BUSINESS_DATE} is the scenario day i of this set: 0 is the oldest (${$.WINDOW_START}), ${$.SCENARIO_COUNT} - 1 the newest (${$.WINDOW_END}). The VaR of the date: VAR <GO>, with its date set to ${$.BUSINESS_DATE}."
  - id: fx
    kind: table
    title: "FX scenarios of this set (one rate per scenario day, per currency)"
    code: "FXS"
    area: right
    rows: "$src"
    empty: "No FX scenarios for this set"
    columns:
      - { label: "FX scenario", bind: "@.FX_SCENARIO_ID", link: true }
      - { label: "Currency", bind: "@.CURRENCY" }
      - { label: "Rate today", bind: "@.RATE" }
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
keys: { F9: "raw" }
